import { Component, forwardRef, input } from '@angular/core';
import { FormsModule, NG_VALUE_ACCESSOR } from '@angular/forms';
import { NzColorPickerModule } from 'ng-zorro-antd/color-picker';
import type { NzPresetColor } from 'ng-zorro-antd/color-picker';
import { HrmControl } from '../shared/hrm-control';

/** Bảng màu định sẵn cho hrm-color-picker (label + danh sách hex). Re-export
 *  kiểu của ng-zorro để consumer khỏi import trực tiếp từ ng-zorro. */
export type HrmColorPreset = NzPresetColor;

/** hrm-color-picker — CVA string (hex), bọc nz-color-picker. */
@Component({
  selector: 'hrm-color-picker',
  imports: [FormsModule, NzColorPickerModule],
  template: `
    <nz-color-picker
      [ngModel]="value()"
      (ngModelChange)="emit($event)"
      [nzSize]="size() === 'sm' ? 'small' : size() === 'lg' ? 'large' : 'default'"
      [nzShowText]="showText()"
      [nzPresets]="presets().length ? presets() : null"
      [nzDisabled]="disabled()"></nz-color-picker>
  `,
  host: { class: 'hrm-color-picker' },
  providers: [{ provide: NG_VALUE_ACCESSOR, useExisting: forwardRef(() => HrmColorPicker), multi: true }],
})
export class HrmColorPicker extends HrmControl<string> {
  readonly size = input<'sm' | 'md' | 'lg'>('md');
  readonly showText = input(true);
  /** Bảng màu gợi ý sẵn trong popover; [] = dùng mặc định của ng-zorro. */
  readonly presets = input<HrmColorPreset[]>([]);
}
